      + L("s3", "inset:0", c(`<div style="font:500 40px ${sans(S)}">sem</div><div style="margin:14px 0">${glass(`<b style="font:800 64px ${sans(S)}"><span style="color:${AMB}">nunca</span> ter editado</b>`)}</div><div style="font:500 36px ${sans(S)};color:rgba(255,255,255,.7)">nada na vida</div><div style="position:relative;display:inline-block;margin-top:40px;font:700 52px ${sans(S)};color:${OR}">um editor<i class="st" style="position:absolute;left:-10px;right:-10px;top:50%;height:6px;background:${OR}"></i></div>`, S.H * 0.3))
      + L("s4", "inset:0", c(`<div style="font:600 40px ${sans(S)};margin-bottom:28px">Você descreve o vídeo <b style="color:${AMB}">exatamente como você quer</b></div><div style="text-align:left;border-radius:22px;background:rgba(18,10,8,.92);border:1.5px solid rgba(255,255,255,.18);box-shadow:0 0 60px ${OR}55;padding:24px 28px"><div style="font:600 18px ${MONO};color:rgba(255,255,255,.5)">● ● ● &nbsp; terminal · pronto</div><div style="font:500 24px ${MONO};color:rgba(255,255,255,.55);margin-top:18px">› O que vamos criar hoje?</div><div style="font:500 28px/1.45 ${MONO};color:#fff;margin-top:12px">› <span class="ty">Crie um vídeo vertical com fundo escuro, luz quente e tipografia que balança</span><i style="display:inline-block;width:14px;height:30px;background:${OR};vertical-align:-5px;margin-left:4px"></i></div></div>`, S.H * 0.28))
      + L("s5", `inset:0;background:${CRE}`, A(`left:0;width:${S.W}px;top:${S.H * 0.24}px;text-align:center;font:italic 400 760px/1 ${serif(S)};color:#141414`, "E"))
      + L("s6", `inset:0;background:${CRE}`, A(`left:90px;top:${S.H * 0.34}px;color:#141414`, `<div style="font:900 110px/1 ${sans(S)};letter-spacing:-.04em">Tipografia</div><div style="font:500 60px ${sans(S)};color:#b9b2a4;margin:14px 0">que</div><div class="bar" style="display:inline-block;padding:6px 26px;background:${OR};font:900 100px/1.1 ${sans(S)};letter-spacing:-.03em;color:#fff">sincroniza</div>`) + `<i style="position:absolute;right:120px;top:${S.H * 0.22}px;width:180px;height:180px;border-radius:50%;background:conic-gradient(${OR} 0 25%,${AMB} 0 100%)"></i>`)
      + L("s7", `inset:0;background:${OR}`, A(`left:0;width:${S.W}px;top:${S.H * 0.42}px;text-align:center;font:900 200px/1 ${sans(S)};letter-spacing:-.05em;color:#fff`, "Cores"))
      + L("s8", "inset:0;background:#000", A(`left:0;top:${S.H * 0.38}px;width:${S.W}px;height:${S.H * 0.24}px;background:#160a06;overflow:hidden`, `<i class="streak" style="position:absolute;left:-40%;top:50%;width:40%;height:4px;background:linear-gradient(90deg,transparent,${AMB},transparent);box-shadow:0 0 30px ${AMB}"></i><div style="position:absolute;left:0;right:0;top:44%;text-align:center;font:500 72px ${sans(S)};letter-spacing:.32em;color:#f3e2cc">CINEMATOGRÁFICO</div>`))
      + L("s9", "inset:0", c(`<div style="font:500 44px ${sans(S)};margin-bottom:30px">clicando no</div><span class="cta" style="display:inline-block;padding:26px 60px;border-radius:999px;background:linear-gradient(180deg,${AMB},${OR});color:#1a0600;font:800 56px ${sans(S)};box-shadow:0 0 0 10px ${OR}33,0 0 70px ${OR}aa">Link abaixo ↓</span>`, S.H * 0.4));
