      + L("b5", `inset:0;background:${OR}`, t(`<div style="font:900 120px/1 ${sans(S)};color:#140600">CRIAR<br>VÍDEOS</div><div style="height:60px"></div><div style="font:900 190px/1 ${sans(S)};color:#140600">100%</div><div style="margin-top:20px">${pill("COM IA", "#140600", OR, `font:900 62px ${sans(S)};padding:12px 46px`)}</div>`, S.H * 0.24))
      + L("b6", "inset:0", t(`<div style="font:900 72px ${sans(S)}">O PASSO A PASSO</div><div style="display:flex;justify-content:center;align-items:center;gap:0;margin:50px 0">${[1, 2, 3].map((n) => `<b class="st${n}" style="width:100px;height:100px;border-radius:50%;background:${n < 3 ? OR : "#222"};color:#fff;display:grid;place-items:center;font:900 48px ${sans(S)}">${n < 3 ? "✓" : "3"}</b>${n < 3 ? `<i style="width:120px;height:6px;background:${OR}"></i>` : ""}`).join("")}</div><div style="font:900 56px ${sans(S)}">COMPLETO ESTÁ NO</div><div style="margin-top:28px">${pill("LINK NA BIO ↑", OR, "#140600", `font:900 60px ${sans(S)};padding:18px 50px`)}</div>`, S.H * 0.3))
      + L("b7", "inset:0", t(`<div style="font:900 56px ${sans(S)}">VOCÊ FICOU</div><div class="stay" style="font:900 170px/1.1 ${sans(S)};color:${OR}">00:15</div><div style="font:700 30px ${sans(S)};color:#aaa;letter-spacing:.1em">ASSISTINDO ATÉ AQUI</div><div style="margin-top:50px">${pill("LINK NA BIO ↑", OR, "#140600", `font:900 60px ${sans(S)};padding:18px 50px`)}</div>`, S.H * 0.32));
