    alCut(tl, el, ".b1", 0, 3.4); alCount(tl, el, ".b1 .fr", 425, 0, 0, 2.8); tl.to(el.querySelector(".b1 .ndl"), { y: 420 + 120, duration: 2.8, ease: "power2.in" }, 0); tl.to(el.querySelector(".b1 .bal"), { scale: 1.08, duration: 2.8, ease: "power1.in" }, 0); tl.to(el.querySelector(".b1 .bal"), { scale: 1.4, opacity: 0, duration: 0.12 }, 2.85);
    el.querySelectorAll(".b1 .frag").forEach((f) => { const a = (+f.dataset.a * Math.PI) / 180; tl.fromTo(f, { opacity: 1, x: 0, y: 0, rotation: 0 }, { opacity: 0, x: Math.cos(a) * 520, y: Math.sin(a) * 520, rotation: 220, duration: 0.55, ease: "power2.out", immediateRender: false }, 2.85); });
    alShow(tl, el, ".b2", 3.5, 5.0); tl.from(el.querySelector(".b2 .sec"), { scale: 1.6, duration: 0.4, ease: "back.out(1.6)" }, 3.5); alShow(tl, el, ".b3", 5.1, 6.1); alShow(tl, el, ".b4", 6.2, 9.0); alSeq(tl, el, ".b4 .cd", 6.4, 0.45); alStrike(tl, el, ".b4 .sk", 7.9, 0.25);
