      + box("u3", `<div style="width:620px;height:96px;border-radius:999px;background:#fff;box-shadow:0 18px 50px rgba(0,0,0,.18);position:relative"><span style="position:absolute;left:34px;top:30px;font:700 30px ${sans(S)};color:#111">🔊</span><i style="position:absolute;left:100px;right:40px;top:44px;height:10px;border-radius:5px;background:#ddd"><b class="vol" style="display:block;width:30%;height:100%;border-radius:5px;background:#111"></b></i></div>`)
